def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []

    for word in words:
        if word:  # Skip empty words (in case of multiple spaces)
            ordered_words.append(''.join(sorted(word)))
        else:
            ordered_words.append('')

    result = ''
    word_index = 0
    for char in s:
        if char == ' ':
            result += ' '
        else:
            result += ordered_words[word_index]
